// src/components/Equipment.js
import React from 'react';

function Equipment({ equipment, handleSelect }) {
  // Ensure equipment is an array, or use an empty array as fallback
  if (!Array.isArray(equipment)) {
    console.error('Expected an array but received:', equipment);
    return <p>Invalid equipment data.</p>;
  }

  return (
    <div>
      <h2>Equipment List</h2>
      {equipment.length > 0 ? (
        <ul>
          {equipment.map((item, index) => (
            <li key={index}>
              <h3>{item.Name}</h3>
              <p>Brand: {item.Brand}</p>
              <p>Price: ${item.Price}</p>
              <button onClick={() => handleSelect(item)}>Select</button>
            </li>
          ))}
        </ul>
      ) : (
        <p>No equipment found.</p>
      )}
    </div>
  );
}

export default Equipment;
